package net.battlespades.bot;
import java.util.*;
import net.battlespades.player.SourceRandom;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotFoundationsTest.*;
import static net.battlespades.bot.BotSourceFixture.*;

class BotOwnerPolicyTest {
    static final Map<String,Object> SOURCE=read("bot-owner");
    static BotPopulation.Player population(Object value){var p=map(value);return new BotPopulation.Player(integer(p.get("id")),integer(p.get("generation")),integer(p.get("team")),integer(p.get("class_id")),bool(p.get("bot")),bool(p.get("alive")),bool(p.get("carries")),bool(p.get("visible_combat")),bool(p.get("vip")),bool(p.get("sole_patient_zero")));}
    static final class Population implements BotPopulation.Services {
        final LinkedHashMap<Integer,BotPopulation.Player> players=new LinkedHashMap<>();final List<List<Object>> events=new ArrayList<>();Set<Integer> unsafe=Set.of();int loading;boolean owns,reconnecting;
        public List<BotPopulation.Player> players(){return List.copyOf(players.values());}public int loadingReservations(){return loading;}public boolean ownsPopulation(){return owns;}public boolean reconnecting(){return reconnecting;}
        public boolean add(){for(int id=0;id<10;id++)if(!players.containsKey(id)&&(loading==0||id!=6)){var p=new BotPopulation.Player(id,1,2+id%2,id%4,true,id%3!=0,id%5==0,false,false,false);players.put(id,p);events.add(List.of("add",id));return true;}return false;}
        public boolean remove(BotPopulation.Player p,boolean force){players.remove(p.id());events.add(List.of("remove",p.id(),force));return true;}public boolean retireSafe(BotPopulation.Player p){return !unsafe.contains(p.id());}public int retireRank(BotPopulation.Player p){return p.classId()%3;}
    }
    @Test void processPipeRoundTripsDetachedSourceFramesAndRejectsUnknownObjects()throws Exception{
        var publication=list(SOURCE.get("perception")).stream().map(BotFoundationsTest::map).filter(row->!list(row.get("frames")).isEmpty()).findFirst().orElseThrow();var frame=BotPerceptionTestData.frame(list(publication.get("frames")).getFirst());var raw=new java.io.ByteArrayOutputStream();BotWire.send(raw,new BotProcessSession.Request(null,null,List.of(frame)));var decoded=(BotProcessSession.Request)BotWire.receive(new java.io.ByteArrayInputStream(raw.toByteArray()));assertEquals(frame,decoded.frames().getFirst());
        var intent=new Intent(1,2,3,4,5,6,7,8,Movement.still(),new Look(frame.players().getFirst().eye(),true,2,3,.5,false),6,new Action(ActionKind.DEPLOY,21,frame.players().getFirst().position(),null,"rgb:123456",3,1.5,2,.2,9),Priority.COMBAT,true,true,null,List.of(),"pipe",1,List.of(new Diagnostic("number",12)));raw.reset();var response=new BotProcessSession.Response(false,3,List.of(intent),Map.of("count",2L),Map.of("list",List.of(1,true,"text")),List.of());BotWire.send(raw,response);assertEquals(response,BotWire.receive(new java.io.ByteArrayInputStream(raw.toByteArray())));assertThrows(java.io.IOException.class,()->BotWire.send(new java.io.ByteArrayOutputStream(),new Object()));assertThrows(java.io.IOException.class,()->BotWire.receive(new java.io.ByteArrayInputStream(new byte[]{127,127,127,127})));assertThrows(java.io.IOException.class,()->BotWire.receive(new java.io.ByteArrayInputStream(java.util.Arrays.copyOf(raw.toByteArray(),raw.size()-1))));
    }
    @Test void unchangedPopulationAndClassPoliciesReserveHumanSlotsAndAvoidTeamStacks(){
        for(var item:list(SOURCE.get("population"))){var trace=map(item);var ports=new Population();var population=new BotPopulation(new BotPopulation.Settings(string(trace.get("mode")),5,6,2,10),ports);int index=0;for(var sample:list(trace.get("rows"))){var row=map(sample);ports.players.clear();ports.unsafe=new HashSet<>();for(var value:list(row.get("players"))){var p=population(value);ports.players.put(p.id(),p);if(bool(map(value).get("unsafe")))ports.unsafe.add(p.id());}ports.loading=integer(row.get("loading"));ports.owns=bool(row.get("owns"));ports.reconnecting=bool(row.get("reconnecting"));ports.events.clear();population.maintain(real(row.get("now")));if(bool(row.get("make_room")))matches(row.get("room"),population.makeRoom());try{matches(row.get("events"),ports.events);matches(list(row.get("result")).stream().map(BotOwnerPolicyTest::population).map(BotSourceFixture::observe).toList(),ports.players());}catch(AssertionError failure){throw new AssertionError(trace.get("mode")+" frame "+index,failure);}index++;}}
        for(var item:list(SOURCE.get("classes"))){var trace=map(item);var random=new SourceRandom(71);var candidates=list(trace.get("candidates")).stream().map(BotFoundationsTest::integer).toList();var preferred=list(trace.get("preferred")).stream().map(BotFoundationsTest::integer).toList();var counts=new HashMap<Integer,Integer>();map(trace.get("counts")).forEach((key,value)->counts.put(Integer.parseInt(key),integer(value)));for(var sample:list(trace.get("rows"))){var row=map(sample);matches(row.get("result"),BotPopulation.chooseClass(string(trace.get("mode")),bool(trace.get("hardcore")),candidates,counts,preferred,row.get("requested")==null?null:integer(row.get("requested")),random));}}
    }
    @Test void unchangedPrefabAndLoadoutPoliciesPreservePrimaryAndGaussianRandomState(){
        for(var item:list(SOURCE.get("selection"))){var trace=map(item);int classId=integer(trace.get("class_id"));var random=new SourceRandom(71+classId);int index=0;for(var sample:list(trace.get("rows"))){var row=map(sample);try{if(row.get("gaussian")!=null)matches(row.get("gaussian"),random.gauss(0,.1));assertEquals(((Number)row.get("before_hash")).longValue(),random.stateHash());matches(row.get("prefabs"),BotSelection.prefabs(list(row.get("available")).stream().map(BotFoundationsTest::string).toList(),random,integer(row.get("limit"))));matches(row.get("loadout"),BotSelection.loadout(classId,random,list(row.get("disabled")).stream().map(BotFoundationsTest::integer).toList()));assertEquals(((Number)row.get("after_hash")).longValue(),random.stateHash());matches(row.get("seed"),random.below31());matches(row.get("next"),random.random());}catch(AssertionError failure){throw new AssertionError("class "+classId+" selection "+index,failure);}index++;}}
    }
    @Test void unchangedPerceptionPrioritiesRetainObserverCarriersHazardsAndCachedOrdinaryRanks(){
        for(var item:list(SOURCE.get("cohorts"))){var row=map(item);var players=list(row.get("players")).stream().map(BotPlayerTestData::player).toList();var objectives=list(row.get("objectives")).stream().map(BotPerceptionTestData::objective).toList();matches(list(row.get("result")).stream().map(BotPlayerTestData::player).map(BotSourceFixture::observe).toList(),BotPerception.cohort(players,integer(row.get("observer")),objectives));}
        var selector=new BotPerception.Entities();for(var item:list(SOURCE.get("entities"))){var row=map(item);matches(list(row.get("result")).stream().map(BotPerceptionTestData::entity).map(BotSourceFixture::observe).toList(),selector.select(list(row.get("entities")).stream().map(BotPerceptionTestData::entity).toList(),list(row.get("players")).stream().map(BotPlayerTestData::player).toList(),real(row.get("now"))));}
    }
    @Test void unchangedPublicationSeparatesTwelveRowSnapshotBatchesFromBudgetedObserverFrames(){
        var first=map(list(SOURCE.get("cohorts")).getFirst());var actors=list(first.get("players")).stream().map(BotPlayerTestData::player).map(p->new BotPerception.Actor(){public int id(){return p.id();}public Player snapshot(){return p;}}).toList();var observers=actors.subList(0,6).stream().map(p->new BotPerception.Observer(p,1,BotMotorTest.profile(),0)).toList();var objectives=list(first.get("objectives")).stream().map(BotPerceptionTestData::objective).toList();var frames=new ArrayList<Perception>();double[] work={0};var services=new BotPerception.Services(){public List<BotPerception.Observer> observers(){return observers;}public List<BotPerception.Actor> players(){return new ArrayList<>(actors);}public List<Entity> entities(){return List.of();}public List<Objective> objectives(){return objectives;}public Map<String,Object> community(){return Map.of();}public void footsteps(List<BotPerception.Actor> p,double now){}public List<BotState.Stimulus> stimuli(BotPerception.Observer observer,double now){return List.of();}public long mapEpoch(){return 7;}public long modeEpoch(){return 1;}public long topology(){return 0;}public String mode(){return "tdm";}public String phase(){return "";}public String behavior(){return "classic";}public boolean friendlyMischief(){return true;}public void submit(Perception f){frames.add(f);}};var perception=new BotPerception(services,10,.75,()->{work[0]+=.0002;return work[0];});int index=0;for(var item:list(SOURCE.get("perception"))){var row=map(item);frames.clear();work[0]=0;try{matches(row.get("result"),perception.publishDue(real(row.get("now"))));matches(list(row.get("frames")).stream().map(BotPerceptionTestData::frame).map(BotSourceFixture::observe).toList(),frames);matches(row.get("next"),observers.stream().map(BotPerception.Observer::next).toList());}catch(AssertionError failure){throw new AssertionError("publication frame "+index,failure);}index++;}
    }
}
